  ["creature.larva.dmg2014"]={title="Larva",subtitle="Criatura - DMG - 2014",body="Pagina: 63\n\n=== ESTATISTICAS ===\n\nTipo/Tamanho: fiend / M\n\nCR: 0\n\nCA: 9\n\nPV: 9 (2d8)\n\nDeslocamento: walk: 20\n\nSTR 9 | DEX 9 | CON 10 | INT 6 | WIS 10 | CHA 2\n\nIdiomas: understands the languages it knew in life but can't speak\n\n=== ACOES ===\n\nBite\n\nmw 1 to hit, reach 5 ft., one target. h1 (1d4 - 1) piercing damage."},
  ["creature.larva.xmm2024"]={title="Larva",subtitle="Criatura - XMM - 2024",body="Pagina: 193\n\n=== ESTATISTICAS ===\n\nTipo/Tamanho: fiend / M\n\nCR: 0\n\nCA: 9\n\nPV: 9 (2d8)\n\nDeslocamento: walk: 20\n\nSTR 9 | DEX 9 | CON 10 | INT 6 | WIS 10 | CHA 2\n\nSentidos: Darkvision 60 ft.\n\nIdiomas: understands Common plus one other language but can't speak\n\n=== ACOES ===\n\nBite\n\nm 1, reach 5 ft. h1 (1d4 - 1) Necrotic damage."},
